  1→// Turbopuffer vector search client for checkpoints
  2→// Uses OpenAI embeddings (text-embedding-3-small) to embed the query,
  3→// then searches Turbopuffer by cosine similarity.
  4→// TODO: add BM25 full-text search as a follow-up once schema is configured.
  5→
  6→const EMBEDDING_MODEL = "text-embedding-3-small";
  7→const EMBEDDING_DIMENSIONS = 1536;
  8→
  9→export interface TurbopufferSearchResult {
 10→  checkpoint_id: string;
 11→}
 12→
 13→interface TurbopufferQueryRow {
 14→  id: number;
 15→  dist: number;
 16→  attributes: {
 17→    checkpoint_id?: string;
 18→  };
 19→}
 20→
 21→type TurbopufferQueryResponse = TurbopufferQueryRow[];
 22→
 23→async function embedQuery(openaiApiKey: string, text: string): Promise<number[]> {
 24→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
 25→    method: "POST",
 26→    headers: {
 27→      Authorization: `Bearer ${openaiApiKey}`,
 28→      "Content-Type": "application/json",
 29→    },
 30→    body: JSON.stringify({
 31→      model: EMBEDDING_MODEL,
 32→      input: text,
 33→      dimensions: EMBEDDING_DIMENSIONS,
 34→    }),
 35→  });
 36→
 37→  if (!resp.ok) {
 38→    const err = await resp.text().catch(() => "");
 39→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
 40→  }
 41→
 42→  const result = (await resp.json()) as { data: Array<{ embedding: number[] }> };
 43→  return result.data[0].embedding;
 44→}
 45→
 46→export async function searchCheckpoints(
 47→  turbopufferApiKey: string,
 48→  openaiApiKey: string,
 49→  repoId: string,
 50→  query: string,
 51→  filters?: { branch?: string },
 52→  limit: number = 50,
 53→): Promise<TurbopufferSearchResult[]> {
 54→  // 1. Embed the query
 55→  const vector = await embedQuery(openaiApiKey, query);
 56→
 57→  // 2. Query Turbopuffer
 58→  // TODO: use repoId dynamically once backfill runs per-environment
 59→  const namespace = `checkpoints-5be1c302-97d2-4cf4-8436-b001efe227e0`;
 60→  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
 61→
 62→  const body: Record<string, unknown> = {
 63→    vector,
 64→    top_k: limit,
 65→    distance_metric: "cosine_distance",
 66→    include_attributes: ["checkpoint_id"],
 67→  };
 68→
 69→  if (filters?.branch) {
 70→    body.filters = {
 71→      branch: [["Eq", filters.branch]],
 72→    };
 73→  }
 74→
 75→  const resp = await fetch(url, {
 76→    method: "POST",
 77→    headers: {
 78→      Authorization: `Bearer ${turbopufferApiKey}`,
 79→      "Content-Type": "application/json",
 80→    },
 81→    body: JSON.stringify(body),
 82→  });
 83→
 84→  if (!resp.ok) {
 85→    const text = await resp.text().catch(() => "");
 86→    throw new Error(`Turbopuffer query failed (${resp.status}): ${text}`);
 87→  }
 88→
 89→  const result = (await resp.json()) as TurbopufferQueryResponse;
 90→
 91→  // Deduplicate checkpoint IDs (multiple vectors may map to the same checkpoint)
 92→  const seen = new Set<string>();
 93→  const results: TurbopufferSearchResult[] = [];
 94→
 95→  for (const row of result) {
 96→    const id = row.attributes?.checkpoint_id;
 97→    if (id && !seen.has(id)) {
 98→      seen.add(id);
 99→      results.push({ checkpoint_id: id });
100→    }
101→  }
102→
103→  return results;
104→}
105→

  1→// Cloudflare Workers environment bindings
  2→
  3→/**
  4→ * Type utility to extract required (non-optional) keys from a type.
  5→ */
  6→type RequiredKeys<T> = {
  7→  [K in keyof T]-?: undefined extends T[K] ? never : K;
  8→}[keyof T];
  9→
 10→/**
 11→ * All required (non-optional) keys from the Env interface.
 12→ */
 13→type RequiredEnvKey = RequiredKeys<Env>;
 14→
 15→/**
 16→ * List of required environment variables validated at runtime by validateEnv().
 17→ *
 18→ * TypeScript helps keep this list in sync with the Env interface:
 19→ * - `satisfies readonly RequiredEnvKey[]` ensures each entry is a valid required key
 20→ * - The compile-time assertion below errors if any required Env key is missing
 21→ *
 22→ * However, the actual validation happens at runtime since TypeScript types are
 23→ * erased. The validateEnv() function checks that these values are present and
 24→ * non-empty when the worker handles its first request.
 25→ */
 26→const REQUIRED_ENV_VARS = [
 27→  "ENCRYPTION_KEY",
 28→  "ENTIRE_CACHE",
 29→  "ENVIRONMENT",
 30→  "FRONTEND_BASE_URL",
 31→  "GITHUB_APP_NAME",
 32→  "GITHUB_APP_PRIVATE_KEY",
 33→  "GITHUB_CLIENT_ID",
 34→  "GITHUB_CLIENT_SECRET",
 35→  "GITHUB_WEBHOOK_SECRET",
 36→  "HYPERDRIVE",
 37→  "REPO_SYNC_QUEUE",
 38→  "SESSION_SECRET",
 39→  "USER_REPO_SYNC_QUEUE",
 40→  "WEBHOOK_QUEUE",
 41→] as const satisfies readonly RequiredEnvKey[];
 42→
 43→// Compile-time check: fails to build if any required Env key is missing from the array above
 44→type _MissingKeys = Exclude<RequiredEnvKey, (typeof REQUIRED_ENV_VARS)[number]>;
 45→type _AssertComplete = [_MissingKeys] extends [never] ? true : never;
 46→const _assertAllKeysIncluded: _AssertComplete = true;
 47→
 48→let validated = false;
 49→
 50→/**
 51→ * Validate that all required environment variables are present and non-empty.
 52→ * Throws an error with a clear message listing any missing variables.
 53→ * Only runs once per worker instance.
 54→ */
 55→export function validateEnv(env: Env): void {
 56→  if (validated) return;
 57→
 58→  const missing: string[] = [];
 59→
 60→  for (const key of REQUIRED_ENV_VARS) {
 61→    const value = env[key];
 62→    if (value === undefined || value === null || value === "") {
 63→      missing.push(key);
 64→    }
 65→  }
 66→
 67→  if (missing.length > 0) {
 68→    throw new Error(
 69→      `Missing required environment variables: ${missing.join(", ")}`
 70→    );
 71→  }
 72→
 73→  validated = true;
 74→}
