164→  // Queue consumer for webhook retries, repo checkpoint syncs, and user repo syncs
165→  // Note: Cloudflare Queues guarantee that all messages in a batch come from the same queue,
166→  // so we can safely check the first message type to determine batch handling.
167→  async queue(
168→    batch: MessageBatch<WebhookMessage | RepoSyncMessage | UserRepoSyncMessage>,
169→    env: Env
170→  ): Promise<void> {
171→    validateEnv(env);
172→
173→    if (batch.messages.length === 0) {
174→      return;
175→    }
176→
177→    const firstMessage = batch.messages[0]?.body;
178→
179→    // Determine message type from first message
180→    // Cloudflare Queues deliver messages from one queue per batch
181→    if (firstMessage && isRepoSyncMessage(firstMessage)) {
182→      // Process repo checkpoint sync messages
183→      await processRepoSyncBatch(
184→        batch as MessageBatch<RepoSyncMessage>,
185→        env
186→      );
187→    } else if (firstMessage && isUserRepoSyncMessage(firstMessage)) {
188→      // Process user repo sync messages
189→      await processUserRepoSyncBatch(
190→        batch as MessageBatch<UserRepoSyncMessage>,
191→        env
192→      );
193→    } else if (firstMessage && "deliveryId" in firstMessage) {
194→      // Process webhook messages (identified by deliveryId field)
195→      const WEBHOOK_MAX_RETRIES = 5;
196→      const batchStartTime = Date.now();
197→      const batchId = generateBatchId();
198→
199→      // Calculate queue wait times
200→      const queueWaitTimes = batch.messages.map((msg) => Date.now() - msg.timestamp.getTime());
201→      const maxWaitMs = queueWaitTimes.length > 0 ? Math.max(...queueWaitTimes) : 0;
202→
203→      console.log(`[webhook-queue] batch_started`, JSON.stringify({
204→        batchId,
205→        queue: batch.queue,
206→        count: batch.messages.length,
207→        avgQueueWaitMs: avgMs(queueWaitTimes),
208→        maxQueueWaitMs: maxWaitMs,
209→      }));
210→
211→      let successCount = 0;
212→      let retryCount = 0;
213→      let deadLetterCount = 0;
214→      const processingTimes: number[] = [];
215→
216→      for (const msg of batch.messages) {
217→        const msgStartTime = Date.now();
218→        const queueWaitMs = Date.now() - msg.timestamp.getTime();
219→        const webhookResult = await processQueueMessage(
220→          msg.body as WebhookMessage,
221→          msg.attempts,
222→          WEBHOOK_MAX_RETRIES,
223→          queueWaitMs,
224→          getDb(env),
225→          env.ENTIRE_CACHE,
226→          env,
227→          processAllWebhookEvents
228→        );
229→
230→        const processingMs = Date.now() - msgStartTime;
231→        processingTimes.push(processingMs);
232→
233→        if (webhookResult.result === "retry") {
234→          msg.retry();
235→          retryCount++;
236→        } else {
237→          msg.ack();
238→          if (webhookResult.result === "dead-letter") {
239→            deadLetterCount++;
240→          } else {
241→            successCount++;
242→          }
243→        }
244→
245→        console.log(`[webhook-queue] message_processed`, JSON.stringify({
246→          batchId,
247→          deliveryId: (msg.body as WebhookMessage).deliveryId,
248→          result: webhookResult.result,
249→          processingMs,
250→          attempt: msg.attempts,
251→        }));
252→      }
253→
254→      const totalBatchTimeMs = Date.now() - batchStartTime;
255→
256→      if (deadLetterCount > 0) {
257→        const queueSpan = trace.getActiveSpan();
258→        queueSpan?.setAttribute("webhook.queue.dead_letter_count", deadLetterCount);
259→        queueSpan?.setStatus({
260→          code: SpanStatusCode.ERROR,
261→          message: `${deadLetterCount} dead-lettered`,
262→        });
263→      }
264→
265→      console.log(`[webhook-queue] batch_complete`, JSON.stringify({
266→        batchId,
267→        count: batch.messages.length,
268→        successCount,
269→        retryCount,
270→        deadLetterCount,
271→        totalBatchTimeMs,
272→        avgProcessingMs: avgMs(processingTimes),
273→        throughputPerMin: totalBatchTimeMs > 0
274→          ? Math.round((batch.messages.length / totalBatchTimeMs) * 60000)
275→          : 0,
276→      }));
277→    } else {
278→      // Unknown message type - log and ack to prevent infinite retries
279→      console.error(
280→        "[queue] Unknown message type in batch:",
281→        JSON.stringify(firstMessage).slice(0, 200)
282→      );
283→      for (const msg of batch.messages) {
284→        msg.ack();
285→      }
286→    }
287→  },
288→
289→  // Cron trigger for daily reconciliation
290→  async scheduled(
291→    controller: ScheduledController,
292→    env: Env,
293→    ctx: ExecutionContext
294→  ): Promise<void> {
295→    validateEnv(env);
296→
297→    const startedAt = new Date().toISOString();
298→    console.log(`[cron] Reconciliation cron triggered at ${startedAt}`);
299→
300→    ctx.waitUntil(
301→      handleReconciliationCron(env)
302→        .then(async (result) => {
303→          // Store last cron run info in KV
304→          await env.ENTIRE_CACHE.put(
305→            "cron:reconciliation:last_run",
306→            JSON.stringify({
307→              startedAt,
308→              completedAt: new Date().toISOString(),
309→              reposQueued: result.reposQueued,
310→              usersQueued: result.usersQueued,
311→            }),
312→            { expirationTtl: 60 * 60 * 24 * 7 } // Keep for 7 days
313→          );
314→        })
315→        .catch((err) => {
316→          console.error("[cron] Reconciliation failed:", err);
317→        })
318→    );
319→  },
320→};
