155→// --- Attribute Truncation ---
156→
157→function truncateToBytes(str: string | null, maxBytes: number): string | null {
158→  if (str === null) return null;
159→  // Fast path: ASCII strings where 1 char = 1 byte
160→  if (str.length <= maxBytes) return str;
161→  // Truncate by encoding to bytes
162→  const encoder = new TextEncoder();
163→  const encoded = encoder.encode(str);
164→  if (encoded.length <= maxBytes) return str;
165→  // Find the last valid UTF-8 boundary within maxBytes
166→  const truncated = encoded.slice(0, maxBytes);
167→  const decoder = new TextDecoder("utf-8", { fatal: false });
168→  return decoder.decode(truncated);
169→}
