289→
290→async function fetchCheckpointsForRepo(
291→  db: Kysely<DB>,
292→  repoId: string,
293→  limit: number | null,
294→): Promise<CheckpointRow[]> {
295→  // Use the same deferred-join pattern as getCheckpointsForBranch
296→  let idQuery = db
297→    .selectFrom("repo_checkpoint_commits")
298→    .select("id")
299→    .where("repo_id", "=", repoId)
300→    .orderBy("commit_date", "desc");
301→
302→  if (limit) {
303→    idQuery = idQuery.limit(limit);
304→  }
305→
306→  const idRows = await idQuery.execute();
307→  if (idRows.length === 0) return [];
308→
309→  const rows = await db
310→    .selectFrom("repo_checkpoint_commits as cc")
311→    .leftJoin("repo_checkpoints as cp", (join) =>
312→      join
313→        .onRef("cp.repo_id", "=", "cc.repo_id")
314→        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
315→    )
316→    .select([
317→      "cc.checkpoint_id",
318→      "cc.branch",
319→      "cc.commit_sha",
320→      "cc.commit_message",
321→      "cc.commit_author_username",
322→      "cc.commit_date",
323→      "cp.prompt",
324→      "cp.agent",
325→      "cp.created_at",
326→      "cp.files_touched",
327→    ])
328→    .where(
329→      "cc.id",
330→      "in",
331→      idRows.map((r) => r.id),
332→    )
333→    .execute();
334→
335→  return rows.map((row) => {
336→    const filesTouched = row.files_touched as string[] | null;
337→    return {
338→      checkpoint_id: row.checkpoint_id,
339→      branch: row.branch,
340→      agent: row.agent ?? "Claude Code",
341→      commit_author_username: row.commit_author_username,
342→      created_at: row.created_at?.toISOString() ?? row.commit_date?.toISOString() ?? null,
343→      commit_sha: row.commit_sha,
344→      commit_message: row.commit_message,
345→      prompt: row.prompt,
346→      files_touched_str: filesTouched?.join(", ") ?? null,
347→    };
348→  });
349→}
