const EMBEDDING_MODEL = "text-embedding-3-small";
const EMBEDDING_DIMENSIONS = 1536;
const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
const MAX_ATTRIBUTE_BYTES = 3800; // Turbopuffer limit is 4096, leave headroom

function truncateToBytes(str: string | null, maxBytes: number): string | null {
  if (str === null) return null;
  if (str.length <= maxBytes) return str;
  const encoder = new TextEncoder();
  const encoded = encoder.encode(str);
  if (encoded.length <= maxBytes) return str;
  const truncated = encoded.slice(0, maxBytes);
  const decoder = new TextDecoder("utf-8", { fatal: false });
  return decoder.decode(truncated);
}

function buildSearchText(checkpoint: {
  prompt: string | null;
  commit_message: string | null;
  files_touched: string[] | null;
}): string {
  const parts: string[] = [];
  if (checkpoint.prompt) {
    parts.push(`Prompt: ${checkpoint.prompt}`);
  }
  if (checkpoint.commit_message) {
    parts.push(`Commit: ${checkpoint.commit_message}`);
  }
  if (checkpoint.files_touched) {
    parts.push(`Files: ${checkpoint.files_touched.join(", ")}`);
  }
  return parts.join("\n");
}

// Hash checkpoint_id to a deterministic numeric ID for Turbopuffer
// Uses FNV-1a 32-bit hash for fast, well-distributed IDs
function hashToNumericId(checkpointId: string): number {
  let hash = 0x811c9dc5; // FNV offset basis
  for (let i = 0; i < checkpointId.length; i++) {
    hash ^= checkpointId.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193); // FNV prime
  }
  return hash >>> 0; // unsigned 32-bit
}

async function embedTexts(
  openaiApiKey: string,
  texts: string[],
): Promise<number[][]> {
  const resp = await fetch("https://api.openai.com/v1/embeddings", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${openaiApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: EMBEDDING_MODEL,
      input: texts,
      dimensions: EMBEDDING_DIMENSIONS,
    }),
  });

  if (!resp.ok) {
    const err = await resp.text().catch(() => "");
    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
  }

  const result = (await resp.json()) as {
    data: Array<{ index: number; embedding: number[] }>;
  };
