// Index checkpoints into Turbopuffer for vector search
// Builds search text, embeds via OpenAI, and upserts to Turbopuffer
// Returns the number of successfully indexed checkpoints
export async function indexCheckpoints(
  turbopufferApiKey: string,
  openaiApiKey: string,
  repoId: string,
  checkpoints: Array<{
    checkpoint_id: string;
    branch: string | null;
    agent: string | null;
    commit_author_username: string | null;
    created_at: string | null;
    commit_sha: string | null;
    commit_message: string | null;
    prompt: string | null;
    files_touched: string[] | null;
  }>,
): Promise<number> {
  // Build search text and filter out empty entries
  const validCheckpoints: Array<{
    checkpoint: (typeof checkpoints)[number];
    text: string;
  }> = [];

  for (const cp of checkpoints) {
    const text = buildSearchText(cp);
    if (text.trim()) {
      validCheckpoints.push({ checkpoint: cp, text });
    }
  }

  if (validCheckpoints.length === 0) {
    return 0;
  }

  // Truncate texts for embedding model token limit
  const embeddingTexts = validCheckpoints.map((v) =>
    v.text.slice(0, MAX_EMBEDDING_CHARS),
  );

  // Embed all texts in one batch call
  const embeddings = await embedTexts(openaiApiKey, embeddingTexts);

  // Build upsert payload
  const ids: number[] = [];
  const vectors: number[][] = [];
  const attributes: Record<string, (string | null)[]> = {
    checkpoint_id: [],
    branch: [],
    agent: [],
    author: [],
    created_at: [],
    commit_sha: [],
    commit_message: [],
    prompt: [],
    files_touched: [],
    text: [],
  };

  for (let i = 0; i < validCheckpoints.length; i++) {
    const { checkpoint, text } = validCheckpoints[i];
    const filesTouchedStr = checkpoint.files_touched?.join(", ") ?? null;

    ids.push(hashToNumericId(checkpoint.checkpoint_id));
    vectors.push(embeddings[i]);
    attributes.checkpoint_id.push(checkpoint.checkpoint_id);
    attributes.branch.push(checkpoint.branch);
    attributes.agent.push(checkpoint.agent);
    attributes.author.push(checkpoint.commit_author_username);
    attributes.created_at.push(checkpoint.created_at);
    attributes.commit_sha.push(checkpoint.commit_sha);
    attributes.commit_message.push(
      truncateToBytes(checkpoint.commit_message, MAX_ATTRIBUTE_BYTES),
    );
    attributes.prompt.push(
      truncateToBytes(checkpoint.prompt, MAX_ATTRIBUTE_BYTES),
    );
    attributes.files_touched.push(
      truncateToBytes(filesTouchedStr, MAX_ATTRIBUTE_BYTES),
    );
    attributes.text.push(truncateToBytes(text, MAX_ATTRIBUTE_BYTES));
  }

  // Upsert to Turbopuffer using columnar format
  const namespace = `checkpoints-${repoId}`;
  const url = `https://api.turbopuffer.com/v2/vectors/${encodeURIComponent(namespace)}`;

  const resp = await fetch(url, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${turbopufferApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      ids,
      vectors,
      attributes,
      distance_metric: "cosine_distance",
    }),
  });

  if (!resp.ok) {
    const errText = await resp.text().catch(() => "");
    throw new Error(`Turbopuffer upsert failed (${resp.status}): ${errText}`);
  }

  return validCheckpoints.length;
}

