/**
 * Test script: Exercises the search index pipeline locally.
 *
 * Usage:
 *   npx tsx scripts/test-search-index.ts [--repo <full_name>] [--limit <n>] [--dry-run]
 *
 * Environment:
 *   DATABASE_URL           MySQL connection string (defaults to local Docker MySQL)
 *   TURBOPUFFER_API_KEY    Turbopuffer API key (required unless --dry-run)
 *   OPENAI_API_KEY         OpenAI API key for embeddings (required unless --dry-run)
 */

import { Kysely, MysqlDialect } from "kysely";
import { createPool } from "mysql2";
import type { DB } from "../db/types";

// --- Config ---

const EMBEDDING_MODEL = "text-embedding-3-small";
const EMBEDDING_DIMENSIONS = 1536;
const MAX_EMBEDDING_CHARS = 25000;
const MAX_ATTRIBUTE_BYTES = 3800;

// --- CLI ---

interface CliOptions {
  repo: string | null;
  limit: number;
  dryRun: boolean;
}

function parseArgs(): CliOptions {
  const args = process.argv.slice(2);
  const options: CliOptions = { repo: null, limit: 5, dryRun: false };

  for (let i = 0; i < args.length; i++) {
    switch (args[i]) {
      case "--repo":
        options.repo = args[++i];
        break;
      case "--limit":
        options.limit = parseInt(args[++i], 10);
        break;
      case "--dry-run":
        options.dryRun = true;
        break;
      default:
        console.error(`Unknown option: ${args[i]}`);
        process.exit(1);
    }
  }
  return options;
}

// --- Database ---

function createDb(): Kysely<DB> {
  const url =
    process.env.DATABASE_URL ?? "mysql://entire:entire@localhost:3306/entire";
  const parsed = new URL(url);
  return new Kysely<DB>({
    dialect: new MysqlDialect({
      pool: createPool({
        host: parsed.hostname,
        port: Number(parsed.port) || 3306,
        user: decodeURIComponent(parsed.username),
        password: decodeURIComponent(parsed.password),
        database: parsed.pathname.replace("/", ""),
      }),
    }),
  });
}

// --- Helpers (mirroring turbopuffer.ts) ---

function truncateToBytes(str: string | null, maxBytes: number): string | null {
  if (str === null) return null;
  if (str.length <= maxBytes) return str;
  const encoder = new TextEncoder();
  const encoded = encoder.encode(str);
  if (encoded.length <= maxBytes) return str;
  const truncated = encoded.slice(0, maxBytes);
  return new TextDecoder().decode(truncated);
}

function buildSearchText(checkpoint: {
  prompt: string | null;
  commit_message: string | null;
  files_touched_str: string | null;
}): string {
  const parts: string[] = [];
  if (checkpoint.prompt) parts.push(`Prompt: ${checkpoint.prompt}`);
  if (checkpoint.commit_message)
    parts.push(`Commit: ${checkpoint.commit_message}`);
  if (checkpoint.files_touched_str)
    parts.push(`Files: ${checkpoint.files_touched_str}`);
  return parts.join("\n");
}

function hashToNumericId(checkpointId: string): number {
  let hash = 0x811c9dc5;
  for (let i = 0; i < checkpointId.length; i++) {
    hash ^= checkpointId.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193);
  }
  return hash >>> 0;
}

// --- Main ---

async function main() {
  const options = parseArgs();
  const turbopufferApiKey = process.env.TURBOPUFFER_API_KEY;
  const openaiApiKey = process.env.OPENAI_API_KEY;

  if (!options.dryRun) {
    if (!turbopufferApiKey) {
      console.error("TURBOPUFFER_API_KEY is required (or use --dry-run)");
      process.exit(1);
    }
    if (!openaiApiKey) {
      console.error("OPENAI_API_KEY is required (or use --dry-run)");
      process.exit(1);
    }
  }

  console.log("=== Search Index Test ===");
  console.log(`  dry-run: ${options.dryRun}`);
  console.log(`  limit:   ${options.limit}`);
  if (options.repo) console.log(`  repo:    ${options.repo}`);
  console.log();

  // Step 1: Fetch checkpoints from DB
  const db = createDb();

  let repoQuery = db
    .selectFrom("repos")
    .select(["id", "full_name", "checkpoint_count"])
    .where("checkpoint_count", ">", 0);

  if (options.repo) {
    repoQuery = repoQuery.where("full_name", "=", options.repo);
  }

  const repos = await repoQuery.limit(1).execute();

  if (repos.length === 0) {
    console.log("No repos with checkpoints found.");
    await db.destroy();
    return;
  }

  const repo = repos[0];
  console.log(
    `[1/5] Repo: ${repo.full_name} (${repo.checkpoint_count} total checkpoints)`,
  );

  // Step 2: Fetch checkpoint data (simulates db.checkpoints.getByIds)
  const idRows = await db
    .selectFrom("repo_checkpoint_commits")
    .select("id")
    .where("repo_id", "=", repo.id)
    .orderBy("commit_date", "desc")
    .limit(options.limit)
    .execute();

  if (idRows.length === 0) {
    console.log("  No checkpoint commits found.");
    await db.destroy();
    return;
  }

  const rows = await db
    .selectFrom("repo_checkpoint_commits as cc")
    .leftJoin("repo_checkpoints as cp", (join) =>
      join
        .onRef("cp.repo_id", "=", "cc.repo_id")
        .onRef("cp.checkpoint_id", "=", "cc.checkpoint_id"),
    )
    .select([
      "cc.checkpoint_id",
      "cc.branch",
      "cc.commit_sha",
      "cc.commit_message",
      "cc.commit_author_username",
      "cc.commit_date",
      "cp.prompt",
      "cp.agent",
      "cp.created_at",
      "cp.files_touched",
    ])
    .where(
      "cc.id",
      "in",
      idRows.map((r) => r.id),
    )
    .execute();

  console.log(`[2/5] Fetched ${rows.length} checkpoints from DB\n`);

  // Step 3: Build search text
  const checkpoints = rows.map((row) => {
    const filesTouched = row.files_touched as string[] | null;
    return {
      checkpoint_id: row.checkpoint_id,
      branch: row.branch,
      agent: row.agent ?? "Claude Code",
      commit_author_username: row.commit_author_username,
      created_at:
        row.created_at?.toISOString() ??
        row.commit_date?.toISOString() ??
        null,
      commit_sha: row.commit_sha,
      commit_message: row.commit_message,
      prompt: row.prompt,
      files_touched_str: filesTouched?.join(", ") ?? null,
    };
  });

  const textsWithCheckpoints: Array<{
    cp: (typeof checkpoints)[number];
    text: string;
  }> = [];

  for (const cp of checkpoints) {
    const text = buildSearchText(cp);
    if (text.trim()) {
      textsWithCheckpoints.push({ cp, text });
    }
  }

  console.log(`[3/5] Built search text for ${textsWithCheckpoints.length} checkpoints:\n`);

  for (const { cp, text } of textsWithCheckpoints) {
    const numericId = hashToNumericId(cp.checkpoint_id);
    console.log(`  --- ${cp.checkpoint_id} (numeric ID: ${numericId}) ---`);
    console.log(`  branch: ${cp.branch}`);
    console.log(`  agent:  ${cp.agent}`);
    console.log(`  author: ${cp.commit_author_username}`);
    console.log(`  text:   ${text.slice(0, 200)}${text.length > 200 ? "..." : ""}`);
    console.log();
  }

  if (options.dryRun) {
    console.log(`[DRY RUN] Would embed ${textsWithCheckpoints.length} texts and upsert to Turbopuffer`);
    await db.destroy();
    return;
  }

  // Step 4: Embed via OpenAI
  console.log(`[4/5] Embedding ${textsWithCheckpoints.length} texts via OpenAI...`);

  const embeddingTexts = textsWithCheckpoints.map(({ text }) =>
    text.slice(0, MAX_EMBEDDING_CHARS),
  );

  const embeddingStart = Date.now();
  const embResp = await fetch("https://api.openai.com/v1/embeddings", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${openaiApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: EMBEDDING_MODEL,
      input: embeddingTexts,
      dimensions: EMBEDDING_DIMENSIONS,
    }),
  });

  if (!embResp.ok) {
    const errText = await embResp.text().catch(() => "");
    console.error(`  OpenAI embedding failed (${embResp.status}): ${errText}`);
    await db.destroy();
    process.exit(1);
  }

  const embResult = (await embResp.json()) as {
    data: Array<{ index: number; embedding: number[] }>;
    usage: { prompt_tokens: number; total_tokens: number };
  };
  const embeddings = embResult.data
    .sort((a, b) => a.index - b.index)
    .map((item) => item.embedding);

  const embeddingMs = Date.now() - embeddingStart;
  console.log(
    `  Embedded ${embeddings.length} texts in ${embeddingMs}ms (${embResult.usage.total_tokens} tokens)`,
  );

  // Step 5: Upsert to Turbopuffer
  console.log(`\n[5/5] Upserting ${embeddings.length} vectors to Turbopuffer...`);

  const ids: number[] = [];
  const vectors: number[][] = [];
  const attributes: Record<string, (string | null)[]> = {
    checkpoint_id: [],
    branch: [],
    agent: [],
    author: [],
    created_at: [],
    commit_sha: [],
    commit_message: [],
    prompt: [],
    files_touched: [],
    text: [],
  };

  for (let i = 0; i < textsWithCheckpoints.length; i++) {
    const { cp, text } = textsWithCheckpoints[i];
    ids.push(hashToNumericId(cp.checkpoint_id));
    vectors.push(embeddings[i]);
    attributes.checkpoint_id.push(cp.checkpoint_id);
    attributes.branch.push(cp.branch);
    attributes.agent.push(cp.agent);
    attributes.author.push(cp.commit_author_username);
    attributes.created_at.push(cp.created_at);
    attributes.commit_sha.push(cp.commit_sha);
    attributes.commit_message.push(
      truncateToBytes(cp.commit_message, MAX_ATTRIBUTE_BYTES),
    );
    attributes.prompt.push(truncateToBytes(cp.prompt, MAX_ATTRIBUTE_BYTES));
    attributes.files_touched.push(
      truncateToBytes(cp.files_touched_str, MAX_ATTRIBUTE_BYTES),
    );
    attributes.text.push(truncateToBytes(text, MAX_ATTRIBUTE_BYTES));
  }

  const namespace = `checkpoints-${repo.id}`;
  const upsertUrl = `https://api.turbopuffer.com/v2/vectors/${encodeURIComponent(namespace)}`;

  console.log(`  namespace: ${namespace}`);
  console.log(`  url:       ${upsertUrl}`);

  const upsertStart = Date.now();
  const upsertResp = await fetch(upsertUrl, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${turbopufferApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      ids,
      vectors,
      attributes,
      distance_metric: "cosine_distance",
    }),
  });

  const upsertMs = Date.now() - upsertStart;

  if (!upsertResp.ok) {
    const errText = await upsertResp.text().catch(() => "");
    console.error(
      `  Turbopuffer upsert failed (${upsertResp.status}): ${errText}`,
    );
    await db.destroy();
    process.exit(1);
  }

  const upsertResult = await upsertResp.json();
  console.log(
    `  Upserted ${ids.length} vectors in ${upsertMs}ms`,
  );
  console.log(`  Response:`, JSON.stringify(upsertResult));

  // Verify: query back one of the checkpoints
  console.log(`\n=== Verification: searching for first checkpoint ===`);
  const queryText = textsWithCheckpoints[0].text.slice(0, 200);
  console.log(`  Query: "${queryText.slice(0, 80)}..."`);

  const qEmbResp = await fetch("https://api.openai.com/v1/embeddings", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${openaiApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      model: EMBEDDING_MODEL,
      input: queryText,
      dimensions: EMBEDDING_DIMENSIONS,
    }),
  });
  const qEmbResult = (await qEmbResp.json()) as {
    data: Array<{ embedding: number[] }>;
  };
  const queryVector = qEmbResult.data[0].embedding;

  const searchUrl = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}/query`;
  const searchResp = await fetch(searchUrl, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${turbopufferApiKey}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      vector: queryVector,
      top_k: 3,
      distance_metric: "cosine_distance",
      include_attributes: ["checkpoint_id", "prompt"],
    }),
  });

  if (searchResp.ok) {
    const searchResult = (await searchResp.json()) as Array<{
      id: number;
      dist: number;
      attributes: Record<string, string>;
    }>;
    console.log(`  Results (${searchResult.length}):`);
    for (const row of searchResult) {
      console.log(
        `    id=${row.id} dist=${row.dist.toFixed(4)} checkpoint=${row.attributes?.checkpoint_id} prompt="${(row.attributes?.prompt ?? "").slice(0, 60)}..."`,
      );
    }
  } else {
    const errText = await searchResp.text();
    console.error(`  Search failed (${searchResp.status}): ${errText}`);
  }

  console.log("\nDone!");
  await db.destroy();
}

main().catch((err) => {
  console.error("Fatal error:", err);
  process.exit(1);
});

