  1→// Turbopuffer vector search client for checkpoints
  2→// Uses OpenAI embeddings (text-embedding-3-small) to embed the query,
  3→// then searches Turbopuffer by cosine similarity.
  4→// TODO: add BM25 full-text search as a follow-up once schema is configured.
  5→
  6→const EMBEDDING_MODEL = "text-embedding-3-small";
  7→const EMBEDDING_DIMENSIONS = 1536;
  8→const MAX_EMBEDDING_CHARS = 25000; // ~8K tokens, text-embedding-3-small limit is 8192 tokens
  9→const MAX_ATTRIBUTE_BYTES = 3800; // Turbopuffer limit is 4096, leave headroom
 10→
 11→export interface TurbopufferSearchResult {
 12→  checkpoint_id: string;
 13→}
 14→
 15→interface TurbopufferQueryRow {
 16→  id: number;
 17→  dist: number;
 18→  attributes: {
 19→    checkpoint_id?: string;
 20→  };
 21→}
 22→
 23→type TurbopufferQueryResponse = TurbopufferQueryRow[];
 24→
 25→function truncateToBytes(str: string | null, maxBytes: number): string | null {
 26→  if (str === null) return null;
 27→  if (str.length <= maxBytes) return str;
 28→  const encoder = new TextEncoder();
 29→  const encoded = encoder.encode(str);
 30→  if (encoded.length <= maxBytes) return str;
 31→  const truncated = encoded.slice(0, maxBytes);
 32→  const decoder = new TextDecoder();
 33→  return decoder.decode(truncated);
 34→}
 35→
 36→function buildSearchText(checkpoint: {
 37→  prompt: string | null;
 38→  commit_message: string | null;
 39→  files_touched: string[] | null;
 40→}): string {
 41→  const parts: string[] = [];
 42→  if (checkpoint.prompt) {
 43→    parts.push(`Prompt: ${checkpoint.prompt}`);
 44→  }
 45→  if (checkpoint.commit_message) {
 46→    parts.push(`Commit: ${checkpoint.commit_message}`);
 47→  }
 48→  if (checkpoint.files_touched) {
 49→    parts.push(`Files: ${checkpoint.files_touched.join(", ")}`);
 50→  }
 51→  return parts.join("\n");
 52→}
