 65→async function embedTexts(
 66→  openaiApiKey: string,
 67→  texts: string[],
 68→): Promise<number[][]> {
 69→  const resp = await fetch("https://api.openai.com/v1/embeddings", {
 70→    method: "POST",
 71→    headers: {
 72→      Authorization: `Bearer ${openaiApiKey}`,
 73→      "Content-Type": "application/json",
 74→    },
 75→    body: JSON.stringify({
 76→      model: EMBEDDING_MODEL,
 77→      input: texts,
 78→      dimensions: EMBEDDING_DIMENSIONS,
 79→    }),
 80→  });
 81→
 82→  if (!resp.ok) {
 83→    const err = await resp.text().catch(() => "");
 84→    throw new Error(`OpenAI embedding failed (${resp.status}): ${err}`);
 85→  }
 86→
 87→  const result = (await resp.json()) as {
 88→    data: Array<{ index: number; embedding: number[] }>;
 89→  };
 90→  return result.data
 91→    .sort((a, b) => a.index - b.index)
 92→    .map((item) => item.embedding);
 93→}
