178→// Index checkpoints into Turbopuffer for vector search
179→// Builds search text, embeds via OpenAI, and upserts to Turbopuffer
180→// Returns the number of successfully indexed checkpoints
181→export async function indexCheckpoints(
182→  turbopufferApiKey: string,
183→  openaiApiKey: string,
184→  repoId: string,
185→  checkpoints: Array<{
186→    checkpoint_id: string;
187→    branch: string | null;
188→    agent: string | null;
189→    commit_author_username: string | null;
190→    created_at: string | null;
191→    commit_sha: string | null;
192→    commit_message: string | null;
193→    prompt: string | null;
194→    files_touched: string[] | null;
195→  }>,
196→): Promise<number> {
197→  // Build search text and filter out empty entries
198→  const validCheckpoints: Array<{
199→    checkpoint: (typeof checkpoints)[number];
200→    text: string;
201→  }> = [];
202→
203→  for (const cp of checkpoints) {
204→    const text = buildSearchText(cp);
205→    if (text.trim()) {
206→      validCheckpoints.push({ checkpoint: cp, text });
207→    }
208→  }
209→
210→  if (validCheckpoints.length === 0) {
211→    return 0;
212→  }
213→
214→  // Truncate texts for embedding model token limit
215→  const embeddingTexts = validCheckpoints.map((v) =>
216→    v.text.slice(0, MAX_EMBEDDING_CHARS),
217→  );
218→
219→  // Embed all texts in one batch call
220→  const embeddings = await embedTexts(openaiApiKey, embeddingTexts);
221→
222→  // Build upsert payload (row-based format for Turbopuffer v1 API)
223→  const upserts = validCheckpoints.map(({ checkpoint, text }, i) => {
224→    const filesTouchedStr = checkpoint.files_touched?.join(", ") ?? null;
225→    return {
226→      id: hashToNumericId(checkpoint.checkpoint_id),
227→      vector: embeddings[i],
228→      attributes: {
229→        checkpoint_id: checkpoint.checkpoint_id,
230→        branch: checkpoint.branch,
231→        agent: checkpoint.agent,
232→        author: checkpoint.commit_author_username,
233→        created_at: checkpoint.created_at,
234→        commit_sha: checkpoint.commit_sha,
235→        commit_message: truncateToBytes(
236→          checkpoint.commit_message,
237→          MAX_ATTRIBUTE_BYTES,
238→        ),
239→        prompt: truncateToBytes(checkpoint.prompt, MAX_ATTRIBUTE_BYTES),
240→        files_touched: truncateToBytes(filesTouchedStr, MAX_ATTRIBUTE_BYTES),
241→        text: truncateToBytes(text, MAX_ATTRIBUTE_BYTES),
242→      },
243→    };
244→  });
245→
246→  // Upsert to Turbopuffer
247→  const namespace = `checkpoints-${repoId}`;
248→  const url = `https://api.turbopuffer.com/v1/vectors/${encodeURIComponent(namespace)}`;
249→
250→  const resp = await fetch(url, {
251→    method: "POST",
252→    headers: {
253→      Authorization: `Bearer ${turbopufferApiKey}`,
254→      "Content-Type": "application/json",
255→    },
256→    body: JSON.stringify({
257→      upserts,
258→      distance_metric: "cosine_distance",
259→    }),
260→  });
261→
262→  if (!resp.ok) {
263→    const errText = await resp.text().catch(() => "");
264→    throw new Error(`Turbopuffer upsert failed (${resp.status}): ${errText}`);
265→  }
266→
267→  return validCheckpoints.length;
268→}
